import{z as A,x as B,o as r,c as d,q as l,j as i,D as E,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"预取时机与污染","description":"","frontmatter":{"title":"预取时机与污染","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prefetch-timing-pollution.md","filePath":"cs/prefetch-timing-pollution.md","lastUpdated":1791063341000}'),p={name:"cs/prefetch-timing-pollution.md"};function c(m,a,D,h,C,f){const s=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="预取时机与污染" tabindex="-1">预取时机与污染 <a class="header-anchor" href="#预取时机与污染" aria-label="Permalink to &quot;预取时机与污染&quot;">​</a></h1><div class="epigraph"><p>太早：块被踢走，预取白做；太晚：需求 load 仍付缺失；猜错：热行被挤掉，DRAM 带宽还给别人用。</p><footer>—— 据 Srinath et al., Feedback Directed Prefetching, MICRO 2007；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/stride-stream-prefetch">上一课</a> 会发 \\(addr+k\\Delta\\)。\\(k\\) 太大或流已经结束，就变成污染。<a href="/cs/rrip-dead-block">RRIP</a> 给了插入位置，但没有说预取器何时该节流。本课不重检步长。缺口是<strong>及时性与污染的度量，以及用反馈关掉或拉开预取。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>覆盖率：需求 miss 里有多少本可被预取覆盖。准确率：发出的预取里有多少被真正用到。污染：因预取插入而导致的额外需求 miss。带宽：预取占用 DRAM 后，需求 miss 排队变长。四者打架。缺口不是再加一种 \\(\\Delta\\) 检测，而是<strong>运行时看这四者，调 \\(k\\) 或关掉该流。</strong></p><p><span class="marginnote">Feedback Directed Prefetching（FDP）用预取队列里「被需求命中 / 被替换前未用」等计数调节攻击性。许多 LLC 预取器带类似节流。</span></p><p><span class="marginnote">直觉类比：预取像提前订餐——订得太早，菜凉了（块被替换）；订得太晚，照样排长队（缺失照付）；口味订错了，还占掉别人真正想点的位置（污染热行）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条预取带使用位：被需求 load 命中则记成功；被替换时仍未用则记浪费。污染：给被预取踢掉的行记「若还在则会命中」的近似（如 victim 里短期命中）。反馈：准确率低则增大插入 RRPV（更容易被踢）或减小 \\(k\\)；污染高则抑制该 PC 的预取。</p>',9)),(r(),i(o,null,{default:E(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E5%8F%91%E5%87%BA%E9%A2%84%E5%8F%96%22%5D%20--%3E%20USE%5B%22%E9%9C%80%E6%B1%82%E6%98%AF%E5%90%A6%E7%94%A8%E5%88%B0%22%5D%0A%20%20PF%20--%3E%20POLL%5B%22%E6%98%AF%E5%90%A6%E6%8C%A4%E6%8E%89%E7%83%AD%E8%A1%8C%22%5D%0A%20%20USE%20--%3E%20FB%5B%22%E8%B0%83%E8%B7%9D%E7%A6%BB%20%2F%20%E5%BC%80%E5%85%B3%22%5D%0A%20%20POLL%20--%3E%20FB%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"软件预取同样可污染；编译器插入密度过高时，硬件反馈仍适用，或 OS 关硬件预取。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[e("a",{href:"/cs/mlp-memory-parallelism"},"MLP"),t(" 的 MSHR 是共享资源：错预取不仅污染 SRAM，还堵住真缺失的登记。及时性与 DRAM 调度互动：同一 bank 上提前太多会造成行缓冲颠簸。这些不改 ISA，只改 CPI 的访存项。")],-1)),a[6]||(a[6]=e("p",null,"把「预取发出时机」单独拎出来看，三种时机的结局完全不同：",-1)),(r(),i(o,null,{default:E(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A2%84%E5%8F%96%E5%8F%91%E5%87%BA%E6%97%B6%E6%9C%BA%22%5D%20--%3E%20E%5B%22%E5%A4%AA%E6%97%A9%EF%BC%9A%E5%9D%97%E5%85%88%E8%90%BD%E8%BF%9B%20cache%22%5D%0A%20%20E%20--%3E%20EV%5B%22%E9%9C%80%E6%B1%82%E5%88%B0%E6%9D%A5%E5%89%8D%E8%A2%AB%E6%9B%BF%E6%8D%A2%20%E7%99%BD%E5%81%9A%E8%BF%98%E6%8C%A4%E6%8E%89%E7%83%AD%E8%A1%8C%22%5D%0A%20%20T%20--%3E%20R%5B%22%E5%88%9A%E5%A5%BD%EF%BC%9A%E9%9C%80%E6%B1%82%E5%88%B0%E8%BE%BE%E5%89%8D%E5%87%A0%E6%AD%A5%E8%90%BD%E5%9C%B0%22%5D%0A%20%20R%20--%3E%20RV%5B%22%E9%9C%80%E6%B1%82%E5%91%BD%E4%B8%AD%20%E7%BC%BA%E5%A4%B1%E8%A2%AB%E8%A6%86%E7%9B%96%22%5D%0A%20%20T%20--%3E%20L%5B%22%E5%A4%AA%E6%99%9A%EF%BC%9A%E9%9C%80%E6%B1%82%E5%85%88%E5%88%B0%20cache%22%5D%0A%20%20L%20--%3E%20LV%5B%22%E4%BB%8D%E4%BB%98%E5%AE%8C%E6%95%B4%E7%BC%BA%E5%A4%B1%20%E5%B8%A6%E5%AE%BD%E8%BF%98%E8%A2%AB%E7%99%BD%E5%8D%A0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">为什么重要：MSHR 是登记未决访存的簿子，名额有限（常见几十个）。一条错预取占掉一个名额，真正的缺失就得在后面排队，内存级并行度直接掉下来——污染不只是少了几行缓存。</span></p><p>与一致性：预取读可能把行变成 S，干扰他核的 M——多核下预取攻击性更要收敛。分区课会再把带宽和命中分到 QoS 里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入指针追逐的依赖预取器细节。也不把「预取指令作为侧信道」写成攻击教程；机制上预取会改 cache 状态，安全课会用到，这里只记副作用存在。下一课把 cache 容量本身按核切开。</p><p>后课默认：预取必须带反馈；默认攻击性不是最优。多核共享 LLC 时，还要按核或按类别切容量。</p><p><span class="marginnote">常见误区：初学者容易以为预取多多益善。预取读会把 cache 行改成共享态，干扰他核正在写的行；多核共享 LLC 下过度预取，等于拿别人的带宽和容量下自己的赌注。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预取看覆盖、准确、污染、带宽四项，用反馈调 \\(k\\)。</li><li>错预取占用 MSHR 与一致性状态。</li><li>共享 cache 如何按核切开，是下一课分区。</li><li>出处：Srinath et al., <em>MICRO</em>, 2007；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const S=A(p,[["render",c]]);export{P as __pageData,S as default};
